#!/usr/bin/env python3
"""Builds content/g8/maths/u1/s1-1*.json (Grade 8 Maths Unit 1, trial sections 1.1–1.1.3) from docs/G8-MATHS-U1-DESIGN.md."""
import json, os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__))); import refs
ROOT = sys.argv[1]
OUT = os.path.join(ROOT, 'content/g8/maths/u1')
os.makedirs(OUT, exist_ok=True)

BOOK = {"title": "Mathematics Grade 8 Student Textbook", "grade": 8, "subject": "maths", "unit": 1, "unit_title": "Rational Numbers"}

def kw(en, am, d): return {"en": en, "am": am, "def": d, "machine": True}
def ex(en, am): return {"en": {"text": en}, "am": {"text": am, "machine": True}}

# ---------- refreshers (one level down) ----------
REF_MIXED = {"name": "Improper ↔ mixed fractions", "screens": [
    {"kind": "steps", "step": "method", "title": "Change 32/5 to a mixed fraction",
     "text": "Divide the numerator by the denominator.",
     "steps": ["32 ÷ 5 = 6, remainder 2.", "The 6 is the whole number.", "The remainder 2 is the new numerator. Keep the denominator 5.", "So 32/5 = 6 2/5."]},
    {"kind": "mcq", "step": "check", "graded": True, "title": "Your turn", "text": "Which mixed fraction equals 7/3?",
     "opts": ["2 1/3", "1 2/3", "3 1/7", "2 2/3"], "ans": "2 1/3",
     "why": "7 ÷ 3 = 2, remainder 1. So 7/3 = 2 1/3.", "clue": "Divide 7 by 3. What is the remainder?"}]}
REF_SIGNS = {"name": "Negative numbers", "screens": [
    {"kind": "steps", "step": "method", "title": "What −(−15) means",
     "text": "A minus sign in front means \"the opposite of\".",
     "steps": ["The opposite of 15 is −15.", "The opposite of −15 is 15.", "So −(−15) = 15.", "Two minus signs together make a plus."]},
    {"kind": "mcq", "step": "check", "graded": True, "title": "Your turn", "text": "What is −(−8)?",
     "opts": ["8", "−8", "0", "16"], "ans": "8",
     "why": "The opposite of −8 is 8.", "clue": "Find the opposite of −8."}]}

def lesson(sec, slug, pages, title, competency, minutes, keywords, ideas, exercises, test, notes, refreshers=None):
    lid = f"g8.maths.u1.s{slug}"
    n = [0]
    def tag(s):
        n[0] += 1; s["id"] = f"{lid}.{n[0]}"; return s
    for i in ideas:
        for s in i["screens"]: tag(s)
    for e in exercises:
        for s in e["items"]: tag(s)
    for s in test: tag(s)
    L = {"id": lid, "book": dict(BOOK, pages=pages, section=sec), "title": title, "competency": competency, "minutes": minutes,
         "keywords": keywords, "ideas": ideas, "exercises": exercises, "test": test, "notes": notes,
         "review": {"status": "validated"}, "version": 1}
    if refreshers: L["refreshers"] = refreshers
    refs.walk(L)
    json.dump(L, open(os.path.join(OUT, f"s{slug}.json"), "w"), ensure_ascii=False, indent=1)

G, P = True, "practise"

